def _t():

    class _SelfNS:
        pass
    self = _SelfNS()

    class ReentrantIter:

        def __init__(self):
            self.reader = None
            self.n = 0

        def __iter__(self):
            return self

        def __next__(self):
            self.n += 1
            if self.n == 1:
                try:
                    next(self.reader)
                except StopIteration:
                    pass
                return 'a,b'
            if self.n == 2:
                return 'x'
            raise StopIteration
    it = ReentrantIter()
    reader = csv.reader(it)
    it.reader = reader
    try:
        next(reader)
    except csv.Error as _exc:
        pass
    else:
        raise AssertionError('assertRaises: did not raise')
